struct ImpliedMoveSuccess {
    int x;
    double y;

    // Class has no user-defined:
    // 1. Destructor
    // 2. Copy Constructor
    // 3. Copy Assignment Operator
    // 4. Move Constructor
    // 5. Move Assignment Operator

    // Result: Move Ctor and Move Assignment are synthesized.
};

struct BlockingDtor {
    int* data;
    BlockingDtor(int s) : data(new int[s]) {}
    ~BlockingDtor() { delete[] data; }

    // User-defined destructor exists.
    // Result: Synthesis of Move Ctor/Assignment is blocked (C++11/14).
    // Compiler still synthesizes Copy Ctor/Assignment (deprecated behavior).
};

struct ForcedSynthesis {
    int* data;
    ForcedSynthesis(int s) : data(new int[s]) {}
    ~ForcedSynthesis() { delete[] data; } // Blocks implicit synthesis

    // Explicitly request the default generation:
    ForcedSynthesis(ForcedSynthesis&&) = default;
    ForcedSynthesis& operator=(ForcedSynthesis&&) = default;

    // This is often insufficient for resources; 
    // manual move logic or Rule of Zero should be preferred.
};

struct MoveDeletedByCopy {
    MoveDeletedByCopy(const MoveDeletedByCopy&) {} // User-defined Copy Ctor

    // Result: Move Ctor/Assignment are implicitly deleted 
    // (Synthesis fails because a Copy operation was defined).
};
